css:
:root{--ink:#102d46;--muted:#5b7086;--navy:#073b66;--blue:#0877bd;--red:#d7192e;--aqua:#eaf2fb;--mint:#eaf8f4;--line:#dce7ee;--bg:#f5f9fb;--white:#fff;--gold:#dd9a30;--shadow:0 18px 55px rgba(12,52,78,.11)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:16px;line-height:1.6}
a{text-decoration:none;color:inherit}.wrap{width:min(1180px,calc(100% - 40px));margin:auto}
.top{background:var(--navy);color:#d9edf8;font-size:13px}.top .wrap{display:flex;justify-content:space-between;gap:20px;padding:9px 0}
.header{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}
.nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.links{display:flex;gap:25px;color:#486275;font-size:14px;font-weight:600}
.header-right{display:flex;align-items:center;gap:14px}
.call-link{font-weight:800;color:var(--navy);font-size:14px}
.nav-cta{background:var(--red);color:#fff;padding:11px 18px;border-radius:10px;font-weight:800;font-size:13px}
.menu-btn{display:none;border:0;background:none;font-size:24px;color:var(--navy)}
.mobile-drawer{display:none}
.crumb{font-size:13px;color:#7890a0;padding:20px 0}.crumb a{color:var(--blue)}

/* BANNER */
.banner{position:relative;height:360px;overflow:hidden}
.banner img{width:100%;height:100%;object-fit:cover;display:block}
.banner:after{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(7,26,46,.86),rgba(7,26,46,.48))}
.banner-copy{position:absolute;inset:0;z-index:2;display:flex;flex-direction:column;justify-content:center}
.eyebrow{display:inline-flex;align-items:center;gap:8px;color:#ffc9ce;font-size:12px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase}
.eyebrow i{width:7px;height:7px;border-radius:50%;background:var(--red)}
.banner h1{color:#fff;font-family:Manrope;font-size:clamp(28px,4vw,42px);letter-spacing:-1px;margin:12px 0 0;max-width:620px}
.banner-sub{color:#dbe8f5;font-size:15px;margin:14px 0 0;max-width:520px;line-height:1.6}
.banner-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}

/* QUICK ACTIONS */
.quick{padding:34px 0}
.quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.quick-tile{position:relative;height:150px;border-radius:16px;overflow:hidden;display:flex;align-items:flex-end}
.quick-tile img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.quick-tile:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(7,59,102,.9),rgba(7,59,102,.1) 55%)}
.qt-icon{position:absolute;top:14px;left:14px;z-index:2;width:34px;height:34px;border-radius:10px;background:rgba(255,255,255,.92);display:grid;place-items:center;font-size:16px}
.qt-label{position:relative;z-index:2;color:#fff;font:700 15px Manrope;padding:16px;width:100%}

.section{padding:56px 0}
.kicker{color:var(--blue);font-size:12px;text-transform:uppercase;letter-spacing:1.4px;font-weight:800}
.section h2{font:800 clamp(24px,3vw,32px)/1.25 Manrope;letter-spacing:-.8px;margin:9px 0 18px}
.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px}
.section-head p{color:var(--muted);max-width:420px;margin:0}

/* ABOUT */
.about p{font-size:15.5px;line-height:1.85;color:var(--muted);margin:0 0 16px;max-width:800px}

/* BENEFITS */
.benefits{background:var(--bg)}
.benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.benefit{display:flex;gap:14px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px 20px}
.benefit i{width:36px;height:36px;border-radius:10px;background:var(--aqua);color:var(--blue);display:grid;place-items:center;flex:none;font-style:normal;font-size:16px}
.benefit p{margin:0;font-size:13.5px;color:var(--ink);padding-top:6px;line-height:1.55}

/* COUNTRIES */
.country-wrap{display:flex;flex-wrap:wrap;gap:10px}
.country{background:#fff;border:1px solid var(--line);border-radius:999px;padding:10px 18px;font-size:13.5px;font-weight:700;color:var(--navy);display:flex;align-items:center;gap:8px}
.country i{width:8px;height:8px;border-radius:50%;background:var(--red);font-style:normal}

/* GALLERY */
.gallery{background:var(--navy);color:#fff;overflow:hidden}
.gallery .section-head p{color:#b9d2e2}
.arrow-set{display:flex;gap:9px}
.arrow{width:42px;height:42px;border:1px solid rgba(255,255,255,.35);background:transparent;color:#fff;border-radius:50%;font-size:20px;cursor:pointer}
.arrow:hover{background:#fff;color:var(--navy)}
.gallery-row{display:flex;gap:16px;overflow-x:auto;padding:4px 0 6px;scrollbar-width:none;scroll-behavior:smooth}
.gallery-row::-webkit-scrollbar{display:none}
.gallery-card{flex:0 0 240px;border-radius:16px;overflow:hidden;background:#0b4b79;border:1px solid rgba(255,255,255,.12)}
.gallery-card img{width:100%;height:170px;object-fit:cover;display:block}

/* CTA */
.cta-band{background:linear-gradient(120deg,var(--navy),#0b5286);color:#fff;border-radius:22px;padding:34px 32px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.cta-band h2{color:#fff;font:800 22px Manrope;margin:0}
.cta-band p{color:#c9dfef;font-size:13.5px;margin:6px 0 0}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.btn2{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border-radius:10px;font-weight:800;font-size:13.5px}
.btn2.primary{background:#fff;color:var(--navy)}.btn2.secondary{background:rgba(255,255,255,.14);color:#fff}

footer{background:#062d4e;color:#c3d9e7;padding:35px 0}
footer .wrap{display:flex;justify-content:space-between;gap:20px;align-items:center}
footer strong{color:#fff;font-family:Manrope}
footer small{font-size:12px}
.mobile-bar{display:none}

@media(max-width:900px){
  .links,.nav-cta,.call-link{display:none}.menu-btn{display:block}
  .mobile-drawer{position:fixed;inset:68px 0 0 0;background:#fff;z-index:60;padding:24px 22px;overflow-y:auto;box-shadow:0 12px 35px rgba(7,61,120,.16)}
  .mobile-drawer a{display:block;padding:16px 4px;border-bottom:1px solid var(--line);font-weight:700;color:var(--navy)}
  .mobile-drawer.open{display:block}
  .quick-grid{grid-template-columns:1fr 1fr}
  .benefit-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:620px){
  .top .wrap{font-size:11px}.top .wrap span:nth-child(2){display:none}
  .banner{height:auto;min-height:340px;padding:28px 0}.banner-copy{position:relative}.banner h1{font-size:26px}.banner-sub{font-size:14px}.banner-actions .btn2{flex:1;justify-content:center}
  .quick{padding:24px 0}
  .quick-grid{grid-template-columns:1fr 1fr;gap:10px}
  .quick-tile{height:110px}
  .qt-label{font-size:13px;padding:12px}
  .qt-icon{width:28px;height:28px;font-size:13px;top:10px;left:10px}
  .section{padding:38px 0}
  .section-head{display:block}.section-head p{margin-top:12px}
  .benefit-grid{grid-template-columns:1fr}
  .gallery-card{flex:0 0 72%}
  .cta-band{flex-direction:column;text-align:center;padding:26px 20px}
  .cta-band .actions{justify-content:center}
  footer .wrap{display:block}
  footer small{display:block;margin-top:10px}
  .mobile-bar{display:flex;position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid var(--line);z-index:50;padding:9px 12px;gap:9px}
  .mobile-bar a{flex:1;text-align:center;border-radius:9px;padding:10px;font-weight:800;font-size:13px}
  .mobile-bar .call{background:var(--mint);color:#087b73}
  .mobile-bar .book{background:var(--blue);color:#fff}
}

/* Shared homepage header and footer */
:root{--navy-dark:#052f5e;--pale:#eef7fd;--header-h:80px}
.topbar{background:var(--navy-dark);color:#cfe1f2;font-size:.78rem}
.topbar a{color:#fff;font-weight:600}
.site-header{position:sticky;top:0;z-index:1030;background:rgba(255,255,255,.96);backdrop-filter:blur(14px);border-bottom:1px solid #e5edf4;height:var(--header-h)}
.site-header .wrap{height:100%;width:100%;max-width:1320px;margin-inline:auto;padding-inline:1.25rem;display:flex;align-items:center;gap:1rem}
.site-header .logo img{height:46px;width:auto;display:block}
.main-nav{display:flex;align-items:center;gap:.15rem;margin-left:auto}
.main-nav a{padding:.5rem .65rem;border-radius:10px;font-size:.82rem;font-weight:600;color:#244665;white-space:nowrap}
.main-nav a:hover,.main-nav a.active{background:var(--pale);color:var(--blue)}
.btn-arsh{background:var(--red);border:1px solid var(--red);color:#fff;font-weight:600;border-radius:10px;padding:.65rem 1rem;font-size:.86rem}
.btn-arsh:hover{background:#b9132a;border-color:#b9132a;color:#fff}
.header-cta{white-space:nowrap}
.menu-btn{width:44px;height:44px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--navy);font-size:1.5rem;display:none;align-items:center;justify-content:center;padding:0}
.search-btn{width:42px;height:42px;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--navy);font-size:1rem;display:flex;align-items:center;justify-content:center;padding:0;flex:none}
.search-btn:hover{background:var(--aqua);color:var(--blue)}
.sm{position:fixed;inset:0;z-index:1070;display:none;align-items:flex-start;justify-content:center;padding:12vh 1rem 1rem;background:rgba(5,30,60,.6);backdrop-filter:blur(4px)}
.sm.open{display:flex}.sm-box{width:min(640px,100%);background:#fff;border-radius:20px;padding:1.25rem;box-shadow:0 30px 70px rgba(5,30,60,.35)}
.sm-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:.9rem}.sm-head h2{font-size:1.05rem;font-weight:700;margin:0;color:var(--navy)}
.sm-close{width:36px;height:36px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);display:flex;align-items:center;justify-content:center}
.sm-box .input-group-text{height:3rem;background:#f8fbfe;border:1px solid #d3e3f1;border-right:0;border-radius:12px 0 0 12px;color:var(--blue)}
.sm-box .form-control{height:3rem;border:1px solid #d3e3f1;border-left:0;border-right:0;border-radius:0;background:#f8fbfe}
.sm-box .btn{height:3rem;border-radius:0 12px 12px 0}
.sm-chips{display:flex;flex-wrap:wrap;gap:.45rem;margin-top:.9rem}.sm-chips button{border:1px solid var(--line);background:#fff;color:var(--blue);border-radius:999px;padding:.3rem .8rem;font-size:.8rem}
.scrim{position:fixed;inset:0;background:rgba(5,30,60,.55);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.3s;z-index:1040}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(86vw,360px);background:#fff;z-index:1050;transform:translateX(100%);transition:transform .35s;display:flex;flex-direction:column;box-shadow:-20px 0 50px rgba(7,61,120,.2)}
.drawer-open .scrim{opacity:1;visibility:visible}.drawer-open .drawer{transform:none}.drawer-open{overflow:hidden}
.drawer-top{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--line)}
.drawer-top img{height:40px}.drawer-close{width:40px;height:40px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);font-size:1.1rem;padding:0}
.drawer-links{flex:1;overflow-y:auto;padding:.75rem 1rem}.drawer-links a{display:flex;align-items:center;gap:.9rem;padding:.8rem .7rem;border-radius:14px;font-weight:600;font-size:.95rem;color:var(--navy)}
.drawer-links a i{width:38px;height:38px;border-radius:12px;background:var(--pale);color:var(--blue);display:grid;place-items:center;font-size:1.05rem}
.drawer-links a:hover{background:var(--pale)}.drawer-links a::after{content:"\\F285";font-family:"bootstrap-icons";margin-left:auto;color:#9bb3c9;font-size:.8rem}
.drawer-foot{padding:1.1rem 1.25rem 1.5rem;border-top:1px solid var(--line);background:var(--pale)}
.drawer-emerg{display:flex;align-items:center;gap:.75rem;margin-bottom:.9rem;color:var(--navy);font-weight:700}
.drawer-emerg>i{width:40px;height:40px;border-radius:50%;background:var(--red);color:#fff;display:grid;place-items:center}
.drawer-emerg small{display:block;font-weight:500;color:var(--muted)}
.strip{background:linear-gradient(110deg,var(--navy-dark),var(--navy));color:#fff;padding:.9rem 0}
.strip .wrap{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}
.strip .lft{display:flex;align-items:center;gap:.9rem}
.strip-ic{width:38px;height:38px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;flex:none}
.strip b{font-family:Manrope;font-weight:700;font-size:1rem}.strip small{display:block;color:#b9d0e6;font-size:.78rem}
.call{background:var(--red);color:#fff;border-radius:999px;padding:.4rem 1rem;font-size:.85rem;font-weight:600}.call:hover{color:#fff;background:#b9132a}
footer{background:#041f3f;color:#9fb8ce;padding:2.2rem 0 1rem;font-size:.8rem;border-top:3px solid var(--red)}
footer .wrap{display:block;width:100%;max-width:1320px;margin-inline:auto;padding-inline:1.25rem}
footer .row{display:flex;flex-wrap:wrap}
footer .row>[class*="col-"]{box-sizing:border-box}
footer .row .col-lg-5{width:41.6667%}footer .row .col-lg-2{width:16.6667%}footer .row .col-lg-3{width:25%}
@media(max-width:991.98px){footer .row .col-lg-5,footer .row .col-lg-2,footer .row .col-lg-3{width:50%}}
@media(max-width:575.98px){footer .row .col-lg-5,footer .row .col-lg-2,footer .row .col-lg-3{width:100%}}
footer h6{color:#e6f0f9;font-weight:600;font-size:.82rem;margin-bottom:.8rem}
footer a{color:#9fb8ce;display:block;margin-bottom:.4rem}footer a:hover{color:#fff}
footer p{margin:0 0 .8rem;max-width:26rem;line-height:1.55}
footer .fl a{transition:color .2s,padding-left .2s}footer .fl a:hover{padding-left:.25rem}
.social{display:flex;gap:.5rem}.social a{width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;margin:0;color:#cfe1f2}
.social a:hover{background:var(--red)}.fi{display:flex;gap:.55rem;margin-bottom:.45rem;color:#9fb8ce}
.copy{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem;border-top:1px solid rgba(255,255,255,.08);margin-top:1.5rem;padding-top:1rem;font-size:.74rem;color:#7f9bb3}
.copy a{display:inline;margin:0;color:#cfe1f2;font-weight:600}
@media(min-width:1920px){.site-header .wrap,footer .wrap{max-width:1560px}}
@media(max-width:1199.98px){.main-nav{gap:0}.main-nav a{padding:.45rem .4rem;font-size:.78rem}.site-header .logo img{height:42px}}
@media(max-width:991.98px){.main-nav,.header-cta{display:none}.menu-btn{display:flex}.search-btn{margin-left:auto}:root{--header-h:66px}}
@media(max-width:575.98px){footer .copy{display:block}footer .copy span{display:block;margin-bottom:.4rem}.strip .wrap{align-items:flex-start}}
